import numpy as np, math
from math import gcd
from fractions import Fraction
import sympy
from mpmath import zeta
P=list(sympy.primerange(2,100000))
C=np.prod([1-2.0/p**2 for p in P])
M=100000
mu2=np.ones(M+1,bool); mu2[0]=False
for p in range(2,int(M**0.5)+1): mu2[p*p::p*p]=False
g=np.ones(M+1)
for p in sympy.primerange(2,M+1): g[p::p]/=(p*p-2.0)
g[~mu2]=0
m2=np.arange(M+1,dtype=np.int64)**2
def gql(q,l):  # density g(q,l)
    s=0.0
    for m in range(1,2000):
        if not mu2[m]: continue
        d=gcd(m*m,q)
        if l%d==0: s+=sympy.mobius(m)*d/(m*m*q)
    return s
def Phi(q,x):
    gg=np.gcd(m2[1:],q); delta=(m2[1:]//gg).astype(float)
    X=x/(q*delta); fr=X-np.floor(X)
    return C*np.sum(g[1:]*q*delta*(fr*fr/2-fr/2))
def S(t):
    r=C
    for p in sympy.primefactors(t):
        if t%(p*p)==0: r*=(p*p-1)/(p*p-2)
    return r
def kappa(q):
    k=1.0
    for p in P:
        v=0;qq=q
        while qq%p==0: qq//=p; v+=1
        if v==0: e=(1-1/p)*(1+1/p-2/p**2)
        elif v==1: e=(1-1/p)*(1-2/p**2+p**-1.5)
        else: e=(1-1/p)*(1-1/p**2)
        k*=e
    return k
x=10**5
for q in [3,12,50]:
    lhs=2*sum(S(h*q)*(x-h*q) for h in range(1,x//q+1))
    sg2=sum(gql(q,l)**2 for l in range(1,q+1))
    rhs=x*x*sg2 - x*6/math.pi**2 - 2*Phi(q,x)
    print('P3 check q',q,lhs,rhs,lhs/rhs)
x=10**9
for q in [10**5,10**5+1,2*10**5+4,10**6,3*10**6]:
    ph=Phi(q,x); pred=2*float(zeta(-0.5))*kappa(q)*math.sqrt(x*q)
    print('Phi q',q,ph,pred,ph/pred)
EOF
